#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2e6 + 5;

int n, fa[N], head[N], head1[N], head2[N], dfn[N], siz[N], tot;
ll a[N], t[N], ans[N];
struct
{
	int v, next;
} e[N << 1], e1[N << 1], e2[N << 1];

void add(int u, int v)
{
	static int cnt = 0;
	e[++cnt] = {v, head[u]};
	head[u] = cnt;
}

void add1(int u, int v)
{
	static int cnt = 0;
	e1[++cnt] = {v, head1[u]};
	head1[u] = cnt;
}

void add2(int u, int v)
{
	static int cnt = 0;
	e2[++cnt] = {v, head2[u]};
	head2[u] = cnt;
}

void modify(int x, ll v)
{
	for (; x <= n; x += x & -x)
		t[x] += v;
}

ll query(int x)
{
	ll res = 0;
	for (; x; x -= x & -x)
		res += t[x];
	return res;
}

int find(int x) { return !fa[x] ? x : fa[x] = find(fa[x]); }

void init() {}

void dfs1(int u, int fa)
{
	dfn[u] = ++tot;
	siz[u] = 1;
	for (int i = head1[u], v; i; i = e1[i].next)
	{
		if ((v = e1[i].v) == fa)
			continue;
		dfs1(v, u);
		siz[u] += siz[v];
	}
}

void dfs2(int u, int fa)
{
	ans[u] = query(dfn[u] + siz[u] - 1) - query(dfn[u] - 1);
	modify(dfn[u], a[u]);
	for (int i = head2[u], v; i; i = e2[i].next)
	{
		if ((v = e2[i].v) == fa)
			continue;
		dfs2(v, u);
	}
	modify(dfn[u], -a[u]);
}

void solve()
{
	cin >> n;
	for (int i = 1; i <= n; ++i)
		cin >> a[i];
	for (int i = 1, u, v; i < n; ++i)
	{
		cin >> u >> v;
		add(u, v);
		add(v, u);
	}
	for (int i = 1; i <= n; ++i)
	{
		for (int j = head[i], rt; j; j = e[j].next)
		{
			if ((rt = find(e[j].v)) > i)
				continue;
			add1(i, rt);
			fa[rt] = i;
		}
	}
	memset(fa, 0, sizeof fa);
	for (int i = n; i >= 1; --i)
	{
		for (int j = head[i], rt; j; j = e[j].next)
		{
			if ((rt = find(e[j].v)) < i)
				continue;
			add2(i, rt);
			fa[rt] = i;
		}
	}
	dfs1(n, 0);
	dfs2(1, 0);
	for (int i = 1; i <= n; ++i)
		cout << ans[i] << " \n"[i == n];
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}


